import asyncio, functools

def retry(attempts):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*a, **k):
            for _ in range(attempts):
                try:
                    return fn(*a, **k)
                except ConnectionError:
                    pass
            raise ConnectionError("gave up")
        return wrapper
    return deco

calls = 0

@retry(3)
async def fetch():
    global calls
    calls += 1
    raise ConnectionError("down")

async def main():
    try:
        await fetch()
    except ConnectionError as e:
        print("caught", e, calls)

asyncio.run(main())
```
